async function foxAdvancedProxy(req){
 const origin=req.headers.get('origin')||'';
 const allowed=['https://xavier-is-working.com','https://foxpdf-studio-web-production.up.railway.app'];
 const cors={'access-control-allow-origin':allowed.includes(origin)?origin:'https://xavier-is-working.com','vary':'Origin','access-control-allow-methods':'POST,GET,OPTIONS','access-control-allow-headers':'Content-Type','access-control-expose-headers':'Content-Disposition,X-FoxPDF-Details','cache-control':'no-store'};
 if(req.method==='OPTIONS')return new Response('',{status:204,headers:cors});
 const uri=new URL(req.url);
 if(req.method==='GET'&&uri.pathname==='/api/advanced/health'){
  try{const r=await fetch('http://foxpdf-advanced.railway.internal:8000/health',{signal:AbortSignal.timeout(10000)});return new Response(await r.text(),{status:r.status,headers:{...cors,'content-type':'application/json'}})}
  catch(e){return new Response(JSON.stringify({ok:false,detail:'Processing service unavailable'}),{status:503,headers:{...cors,'content-type':'application/json'}})}
 }
 if(req.method!=='POST'||!['/api/advanced/process','/api/advanced/inspect'].includes(uri.pathname))return new Response('Not found',{status:404,headers:cors});
 if(origin&&!allowed.includes(origin))return new Response(JSON.stringify({detail:'Origin not allowed'}),{status:403,headers:{...cors,'content-type':'application/json'}});
 const token=Bun.env.FOXPDF_API_TOKEN;
 if(!token)return new Response(JSON.stringify({detail:'Advanced processing not configured'}),{status:503,headers:{...cors,'content-type':'application/json'}});
 const len=Number(req.headers.get('content-length')||0);
 if(len>21*1024*1024)return new Response(JSON.stringify({detail:'Advanced PDFs must be smaller than 20 MB'}),{status:413,headers:{...cors,'content-type':'application/json'}});
 try{
  const raw=await req.arrayBuffer();
  if(raw.byteLength>21*1024*1024)return new Response(JSON.stringify({detail:'Uploaded file exceeds limit'}),{status:413,headers:{...cors,'content-type':'application/json'}});
  const r=await fetch('http://foxpdf-advanced.railway.internal:8000'+uri.pathname,{method:'POST',headers:{'content-type':req.headers.get('content-type')||'','x-foxpdf-internal-token':token},body:raw,signal:AbortSignal.timeout(120000)});
  const h={...cors,'content-type':r.headers.get('content-type')||'application/octet-stream','content-disposition':r.headers.get('content-disposition')||'','x-foxpdf-details':r.headers.get('x-foxpdf-details')||''};
  return new Response(await r.arrayBuffer(),{status:r.status,headers:h});
 }catch(e){return new Response(JSON.stringify({detail:'Advanced service could not process this request. Please retry.'}),{status:502,headers:{...cors,'content-type':'application/json'}})}
}


/* FOX_PRIVATE_PROXIES_V1: user-facing review & certificate operations */
const foxPrivateOrigins=new Set(['https://xavier-is-working.com','https://www.xavier-is-working.com','https://foxpdf-studio-web-production.up.railway.app']);
const foxProxyCors=o=>({'access-control-allow-origin':foxPrivateOrigins.has(o)?o:'https://xavier-is-working.com','vary':'Origin','cache-control':'no-store','access-control-allow-methods':'OPTIONS,POST,GET','access-control-allow-headers':'content-type','access-control-expose-headers':'content-disposition,x-foxpdf-signature-type'});
async function foxPrivateProxy(req,kind){
 const u=new URL(req.url),o=req.headers.get('origin')||'',cors=foxProxyCors(o);
 if(req.method==='OPTIONS')return new Response('',{status:204,headers:cors});
 if(o&&!foxPrivateOrigins.has(o))return new Response(JSON.stringify({error:'Origin denied'}),{status:403,headers:{...cors,'content-type':'application/json'}});
 const cert=kind==='cert',max=cert?12*1024*1024:6*1024*1024;
 if(Number(req.headers.get('content-length')||0)>max)return new Response(JSON.stringify({error:'Upload exceeds limit'}),{status:413,headers:{...cors,'content-type':'application/json'}});
 const internal='http://foxpdf-private-reviews.railway.internal:8080';
 const allowed=cert?['/api/cert/sign']:['/api/review/create','/api/review/info','/api/review/file','/api/review/comments','/api/review/comment','/api/review/revoke'];
 if(req.method==='GET'&&u.pathname==='/api/review/health'&&!cert){
  try{const r=await fetch(internal+'/health',{signal:AbortSignal.timeout(9000)});return new Response(await r.text(),{status:r.status,headers:{...cors,'content-type':'application/json'}})}
  catch(e){return new Response(JSON.stringify({ok:false}),{status:503,headers:{...cors,'content-type':'application/json'}})}
 }
 if(req.method!=='POST'||!allowed.includes(u.pathname))return new Response(JSON.stringify({error:'Not found'}),{status:404,headers:{...cors,'content-type':'application/json'}});
 if(cert&&!Bun.env.FOX_CERT_GATEWAY_TOKEN)return new Response(JSON.stringify({error:'Certificate service not configured'}),{status:503,headers:{...cors,'content-type':'application/json'}});
 try{
  const body=await req.arrayBuffer();if(body.byteLength>max)return new Response(JSON.stringify({error:'Upload too large'}),{status:413,headers:{...cors,'content-type':'application/json'}});
  const headers={'content-type':req.headers.get('content-type')||'application/octet-stream'};
  if(cert)headers['x-foxpdf-internal-token']=Bun.env.FOX_CERT_GATEWAY_TOKEN;
  else headers['x-forwarded-for']=(req.headers.get('x-forwarded-for')||'anonymous').split(',')[0];
  const r=await fetch(internal+u.pathname,{method:'POST',headers,body,signal:AbortSignal.timeout(90000)});
  const back={...cors,'content-type':r.headers.get('content-type')||'application/octet-stream','content-disposition':r.headers.get('content-disposition')||''};
  return new Response(await r.arrayBuffer(),{status:r.status,headers:back});
 }catch(e){console.error('FOX_PRIVATE_PROXY_FAILURE',kind,String(e).slice(0,120));return new Response(JSON.stringify({error:'Service unavailable. Please try again later.'}),{status:502,headers:{...cors,'content-type':'application/json'}})}
}


