const foxEnc=new TextEncoder();
async function foxSig(text){
 const pw=Bun.env.FOX_ADMIN_PASSWORD;if(!pw)throw Error("Admin password is not configured");
 const key=await crypto.subtle.importKey("raw",foxEnc.encode(pw),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
 const out=new Uint8Array(await crypto.subtle.sign("HMAC",key,foxEnc.encode(text)));
 return Array.from(out,b=>b.toString(16).padStart(2,"0")).join("");
}
async function foxGoodPassword(input){
 const pw=Bun.env.FOX_ADMIN_PASSWORD;if(!pw)return false;
 const a=new Uint8Array(await crypto.subtle.digest("SHA-256",foxEnc.encode(pw)));
 const b=new Uint8Array(await crypto.subtle.digest("SHA-256",foxEnc.encode(input)));
 let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0;
}
function foxTrustedOrigin(req){const allowed=["https://foxpdf-studio-web-production.up.railway.app","https://xavier-is-working.com","https://www.xavier-is-working.com"];if(req.headers.get("sec-fetch-site")==="cross-site")return false;const origin=req.headers.get("origin");if(origin)return allowed.includes(origin);const ref=req.headers.get("referer");return !ref||allowed.some(h=>ref===h||ref.startsWith(h+"/")||ref.startsWith(h+"?")||ref.startsWith(h+"#"))}
const foxFailures=new Map();
async function foxAuthed(req){
 const raw=(req.headers.get("cookie")||"").match(/(?:^|;\s*)foxadm=(\d{13})\.([0-9a-f]{64})(?:;|$)/);if(!raw)return false;
 const age=Date.now()-Number(raw[1]);if(age<0||age>43200000)return false;
 try{return await foxSig(raw[1])===raw[2]}catch{return false}
}

