  const page=String(d.page||"/").replace(/[^A-Za-z0-9/_-]/g,"").slice(0,100);
  if(/\.(pdf|docx|txt)$/i.test(page))return new Response("Document pages not tracked",{status:400});
  const country=["cf-ipcountry","cloudfront-viewer-country","x-vercel-ip-country"].map(k=>req.headers.get(k)).find(v=>/^[a-z]{2}$/i.test(v||""))||"Unknown";
