function v3Time(v){if(v==null||v==="")return null;const x=new Date(v);return Number.isFinite(x.getTime())?x:null}
function v3Field(obj,keys){for(const k of keys)if(obj?.[k]!=null&&obj[k]!=="")return obj[k];return null}
async function v3Legacy(table,limit){try{const cols=await foxAdminDB.unsafe("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1",[table]);if(!cols.length)return {available:false,rows:[]};const names=cols.map(x=>x.column_name),stamp=["visited_at","created_at","timestamp","time","created","ts","date","updated_at"].find(k=>names.includes(k));const order=stamp?' ORDER BY "'+stamp+'" DESC':"";const rows=await foxAdminDB.unsafe('SELECT to_jsonb(t) AS data FROM "'+table+'" t'+order+" LIMIT "+limit);return {available:true,rows:rows.map(x=>x.data||x)}}catch(e){console.error("Admin legacy",table,String(e?.message||e).slice(0,90));return {available:false,rows:[]}}}
async function v3Report(days){
 await v3ready();const cutoff=Date.now()-days*86400000;
 const [now,old,visits,tickets,messages]=await Promise.all([
 foxAdminDB.unsafe("SELECT at,site,action,page,session,country,device,source FROM fox_admin_events_v3 WHERE at>=NOW()-($1::int*INTERVAL '1 day') ORDER BY at DESC LIMIT 6500",[days]),
 foxAdminDB.unsafe("SELECT day,site,event,hits FROM fox_website_counts WHERE day>=CURRENT_DATE-($1::int*INTERVAL '1 day')",[days]).catch(()=>[]),
 v3Legacy("chisa_visits",5000),v3Legacy("chisa_tickets",120),v3Legacy("chisa_messages",120)]);
 const counts={day:new Map(),page:new Map(),country:new Map(),device:new Map(),source:new Map(),section:new Map()};
 let views=0,pdf=0,game=0,hub=0,tools=0;const sessions=new Set(),recent=[],events=[];
 const bump=(key,name,n)=>{const m=counts[key];m.set(name,(m.get(name)||0)+n)};
 function add(x){const t=v3Time(x.at),n=Number(x.n||1);if(t&&t.getTime()<cutoff)return;
 const site=String(x.site||"Other"),action=String(x.action||"view"),page=String(x.page||"/"),country=v3Country(x.country),device=String(x.device||"Unknown"),source=String(x.source||"Unknown");
 bump("section",site,n);
 if(action==="view"){views+=n;bump("page",page,n);bump("country",country,n);bump("device",device,n);bump("source",source,n);if(t)bump("day",t.toISOString().slice(0,10),n);if(site==="pdf")pdf+=n;else if(site==="hub")hub+=n;else if(site==="game")game+=n}
 if(action==="tool"||action==="download")tools+=n;
 if(x.session)sessions.add(String(x.session));
 if(t){const at=t.toISOString();if(action==="view"&&recent.length<90)recent.push({at,section:site,page,country,device,kind:action});if(events.length<100)events.push({at,section:site,action,page})}
 }
 now.forEach(x=>add(x));
 for(const x of old){const n=Math.max(0,Number(x.hits)||0);if(!n||n>1000000)continue;add({at:v3Time(x.day)?.toISOString(),site:x.site,action:x.event==="tool"?"tool":x.event==="hub_entry"?"hub_entry":"view",page:x.site==="pdf"?"/pdf":x.site==="game"?"/game":"/",n})}
 if(visits.available)for(const x of visits.rows){const at=v3Field(x,["visited_at","created_at","timestamp","time","created","ts","date"]);if(!at)continue;const ua=String(v3Field(x,["device","device_type","platform","user_agent"])||"");const country=v3Field(x,["country","country_code","country_name","geo_country"]);const ref=String(v3Field(x,["referrer","source","ref"])||"");const visitor=v3Field(x,["visitor","visitor_id","session_id","session","visitor_hash"]);const path=String(v3Field(x,["path","page","pathname"])||"/game");add({at,site:"game",action:"view",page:path.startsWith("/")?path:"/game",country,device:v3Device(ua),source:v3Source(ref),session:visitor})}
 const list=k=>Array.from(counts[k],([name,count])=>({name,count})).sort((a,b)=>b.count-a.count);
 const trend=[],date=new Date();date.setUTCHours(0,0,0,0);for(let i=days-1;i>=0;i--){const day=new Date(date.getTime()-i*86400000).toISOString().slice(0,10);trend.push({day:day.slice(5),count:counts.day.get(day)||0})}
 const inbox=[];for(const [name,group] of [["Chisa tickets",tickets],["Chisa messages",messages]])if(group.available)for(const x of group.rows){const at=v3Time(v3Field(x,["created_at","sent_at","timestamp","time","date","updated_at"]));if(at&&at.getTime()<cutoff)continue;inbox.push({at:at?.toISOString()||null,source:name,name:String(v3Field(x,["name","sender","nickname","username"])||"Visitor").slice(0,90),email:String(v3Field(x,["email","reply_email"])||"").slice(0,150),subject:String(v3Field(x,["subject","title","topic","category"])||"Support request").slice(0,100),body:String(v3Field(x,["message","body","content","text","description"])||"").slice(0,1200),status:String(v3Field(x,["status","state"])||"Received").slice(0,30)})}
 if(tickets.available&&tickets.rows.length){
  const threadById=new Map();
  if(messages.available)for(const m of messages.rows){const key=String(m.ticket_id??"");if(!threadById.has(key))threadById.set(key,[]);threadById.get(key).push(m)}
  inbox.length=0;
  for(const t of tickets.rows){
   const thread=(threadById.get(String(t.id))||[]).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));
   const userMessage=thread.filter(m=>String(m.author||"").toLowerCase()!=="admin").at(-1)||thread.at(-1);
   const time=v3Time(t.updated_at||t.created_at);
   if(time&&time.getTime()<cutoff)continue;
   inbox.push({ticketId:Number(t.id)||null,at:time?.toISOString()||null,source:"Chisa support",name:String(t.name||"Visitor").slice(0,100),email:"",subject:String(t.subject||t.category||"Support request").slice(0,100),body:String(userMessage?.body||"").slice(0,1200),status:String(t.status||"Open").slice(0,30)});
  }
 }
 inbox.sort((a,b)=>String(b.at).localeCompare(String(a.at)));recent.sort((a,b)=>String(b.at).localeCompare(String(a.at)));events.sort((a,b)=>String(b.at).localeCompare(String(a.at)));
 return {totals:{views,sessions:sessions.size,hub,pdf,game,tools},trend,pages:list("page").slice(0,40),countries:list("country"),devices:list("device"),sources:list("source"),sections:list("section"),visitors:recent.slice(0,70),events:events.slice(0,90),messages:inbox.slice(0,100),coverage:{game:visits.available},notice:visits.available?"Existing Chisa visit records are included. Older records with no country or device information appear as Unknown.":"Direct game visits are not yet available from existing data. Game-entry clicks are tracked separately."};
}
async function v3Admin(req,url){
 if(url.pathname==="/admin/login"||url.pathname==="/admin/logout")return foxLiveAdmin2026(req,url);
 if(url.pathname==="/admin"&&req.method==="GET")return new Response(await foxAuthed(req)?v3Shell:v3Login(),{headers:V3_HTML});
 if(!await foxAuthed(req))return new Response("Unauthorized",{status:401,headers:{"cache-control":"no-store"}});
 const threadUrl=url.pathname.match(/^\/admin\/ticket\/(\d+)(\/reply)?$/);
 if(threadUrl){
  const id=Number(threadUrl[1]);if(!Number.isSafeInteger(id)||id<1)return new Response("Invalid ticket",{status:400});
  if(threadUrl[2]){
   if(req.method!=="POST")return new Response("Method not allowed",{status:405});
   const origin=req.headers.get("origin");if(!foxTrustedOrigin(req))return new Response("Origin denied",{status:403});
   if(Number(req.headers.get("content-length")||0)>5000)return new Response("Reply too long",{status:413});
   const body=await req.json().catch(()=>null),reply=String(body?.reply||"").trim();
   if(!reply||reply.length>3000)return Response.json({error:"Reply must be 1–3000 characters"},{status:400});
   try{
    await foxAdminDB.unsafe("INSERT INTO chisa_messages(ticket_id,author,body) VALUES($1,'admin',$2)",[id,reply]);
    return Response.json({ok:true,detail:"Reply saved in support thread"},{headers:{"cache-control":"no-store"}});
   }catch(err){console.error("Admin reply",String(err?.message||err).slice(0,110));return Response.json({error:"The reply could not be saved"},{status:503})}
  }
  if(req.method!=="GET")return new Response("Method not allowed",{status:405});
  try{const messages=await foxAdminDB.unsafe("SELECT author,body,created_at FROM chisa_messages WHERE ticket_id=$1 ORDER BY created_at ASC LIMIT 150",[id]);return Response.json({messages},{headers:{"cache-control":"no-store"}})}catch{return Response.json({error:"Unable to load this ticket"},{status:503})}
 }
 const days=Math.max(1,Math.min(90,Number(url.searchParams.get("days")||30)));
 if(url.pathname==="/admin/data"&&req.method==="GET"){try{return Response.json(await v3Report(days),{headers:{"cache-control":"no-store"}})}catch(e){console.error("Admin report",String(e?.message||e).slice(0,100));return Response.json({error:"Unavailable"},{status:503})}}
 if(url.pathname==="/admin/export.csv"&&req.method==="GET"){
  try{const r=await v3Report(days),csv=s=>'"'+String(s).replaceAll('"','""').replace(/^[=+\-@]/,"'")+'"',lines=["Category,Name,Count"];for(const [section,items] of [["Pages",r.pages],["Countries",r.countries],["Devices",r.devices],["Sources",r.sources],["Sections",r.sections]])for(const x of items)lines.push([csv(section),csv(x.name),Number(x.count||0)].join(","));return new Response(lines.join("\r\n"),{headers:{"content-type":"text/csv; charset=utf-8","content-disposition":'attachment; filename="fullsite-analytics.csv"',"cache-control":"no-store"}})}catch{return new Response("Export unavailable",{status:503})}
 }
 return new Response("Not found",{status:404});
}

const v3Hub=hubPage.replace('<style>','<style>.loader{display:none!important}').replace('href="/pdf"','href="https://xavier-is-working.com/pdf"').replace('</main>','<div style="text-align:center;margin:18px auto;font:12px system-ui"><a style="color:#dbb6df;text-decoration:underline" href="https://foxpdf-studio-web-production.up.railway.app/admin">Admin login</a></div></main>').replace('</body>','<script defer data-section="hub" src="'+V3_ASSETS+'tracker-v3.js?v=3.2"></script></body>');
const v3PdfBase=page.replace("interactive-editor-v6.js?v=13.1","interactive-editor-v6.js?v=18.7").replace("interactive-editor-v6.css?v=13.1","interactive-editor-v6.css?v=18.2").replace("gold-dashboard-v4.js?v=13.1","gold-dashboard-v4.js?v=18.0").replace("gold-dashboard-v4.css?v=13.0","gold-dashboard-v4.css?v=18.0").replace('</body>','<script defer data-section="pdf" src="'+V3_ASSETS+'tracker-v3.js?v=3.2"></script></body>');
const v3Pdf=v3PdfBase.replace(/interactive-editor-v6.js\?v=[0-9.]+/g,"interactive-editor-v6.js?v=19.0").replace(/task-picker-v13.js\?v=[0-9.]+/g,"task-picker-v13.js?v=19.0").replace("</body>",'<script defer src="/fox-assets/integrity-tools-v1.js?v=1.0"></script></body>');


async function foxIntegrityProxy(req){
 const origin=req.headers.get("origin")||"";
 const allowed=["https://xavier-is-working.com","https://foxpdf-studio-web-production.up.railway.app"];
 const cors={"access-control-allow-origin":allowed.includes(origin)?origin:allowed[1],"vary":"Origin","access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"Content-Type","access-control-expose-headers":"Content-Disposition,X-FoxPDF-Details","cache-control":"no-store"};
 const path=new URL(req.url).pathname;
 if(req.method==="OPTIONS")return new Response(null,{status:204,headers:cors});
 if(origin&&!allowed.includes(origin))return Response.json({detail:"Origin not allowed"},{status:403,headers:cors});
 const endpoint=path.slice("/api/integrity".length);
 if(!((req.method==="GET"&&endpoint==="/health")||(req.method==="POST"&&["/inspect","/process"].includes(endpoint))))return new Response("Not found",{status:404,headers:cors});
 try{
  const headers={};let body;
  if(req.method==="POST"){
   const token=Bun.env.FOXPDF_API_TOKEN;
   if(!token)return Response.json({detail:"Processing is not configured"},{status:503,headers:cors});
   if(Number(req.headers.get("content-length")||0)>21*1024*1024)return Response.json({detail:"PDF exceeds 20 MB"},{status:413,headers:cors});
   body=await req.arrayBuffer();if(body.byteLength>21*1024*1024)return Response.json({detail:"PDF exceeds 20 MB"},{status:413,headers:cors});
   headers["content-type"]=req.headers.get("content-type")||"";headers["x-foxpdf-internal-token"]=token;
  }
  const response=await fetch("http://127.0.0.1:8000"+endpoint,{method:req.method,headers,body,signal:AbortSignal.timeout(180000)});
  return new Response(await response.arrayBuffer(),{status:response.status,headers:{...cors,"content-type":response.headers.get("content-type")||"application/octet-stream","content-disposition":response.headers.get("content-disposition")||"","x-foxpdf-details":response.headers.get("x-foxpdf-details")||""}});
 }catch{return Response.json({detail:"The verified processing engine is unavailable. Your original PDF is unchanged."},{status:503,headers:cors})}
}

Bun.serve({port:Number(Bun.env.PORT||3000),maxRequestBodySize:22*1024*1024,async fetch(req){const url=new URL(req.url);if(url.pathname.startsWith('/api/integrity/'))return foxIntegrityProxy(req);if(url.pathname==='/api/site/track')return v3Track(req);if(url.pathname.startsWith('/admin'))return v3Admin(req,url);if(url.pathname.startsWith('/fox-assets/'))return foxLiveAsset(req,url);if(url.pathname.startsWith('/api/advanced'))return foxAdvancedProxy(req);if(url.pathname.startsWith('/api/review/'))return foxPrivateProxy(req,'review');if(url.pathname.startsWith('/api/cert/'))return foxPrivateProxy(req,'cert');if(req.method!=="GET")return new Response("Method not allowed",{status:405});if(url.pathname==="/health")return Response.json({ok:true,app:"FoxPDF Studio Web Beta",processing:"in-browser"});if(url.pathname==="/")return new Response(v3Hub,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}});if(url.pathname==="/pdf")return new Response(v3Pdf,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","content-security-policy":"default-src 'self' https: data: blob:; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net https://xavieraponteus-source.github.io https://foxpdf-studio-web-production.up.railway.app; style-src 'self' 'unsafe-inline' https://xavieraponteus-source.github.io https://foxpdf-studio-web-production.up.railway.app https://fonts.googleapis.com; img-src 'self' https: data: blob:; frame-src blob:; object-src 'none'; base-uri 'none'; form-action 'self'","x-content-type-options":"nosniff"}});return new Response("Not found",{status:404})}});






